Let us fix some conventions. Throughout, $T^{\top}$ denotes the transpose of the operator $T$, acting on linear forms, no Hilbert space adjoint is ever considered. The Pochhammer symbol is $(a)_k=a(a+1)\cdots(a+k-1)$, $(a)_0=1$, and the generalized hypergeometric series are denoted as usual by
\begin{equation}
    \,\mbox{}_{p}F_{ q}\!\left(\begin{array}{c} a_1,\dots,a_p\\b_1,\dots,b_q\end{array} ; z\right)=\sum_{k\geq 0}\frac{(a_1)_k\cdots (a_p)_k}{(b_1)_k\cdots(b_q)_k}\frac{z^k}{k!}.
\end{equation}

\label{prop:PostiveType}
    Two-diagonal irreducible representations of the positive type of $m\mathfrak{H}$ acting on ${\mathbb C}^{\mathbb N}$ are described by the following operators
\begin{align}
    Z\mid{n}\,\rangle&=\delta\mid{n}\,\rangle+a_n\mid{n-1}\,\rangle,\\
    X\mid{n}\,\rangle&=(n(1+2\delta)+\alpha)\mid{n}\,\rangle+a_n(n+\beta)\mid{n-1}\,\rangle,\\
    V\mid{n}\,\rangle&=-(n+\beta)(\beta+n+1)\mid{n}\,\rangle-\frac{(n+1)(2\alpha+\eta+n(1+2\delta))}{a_{n+1}}\mid{n+1}\,\rangle,
\end{align}
with $a_n\neq 0$ for all $n\in {\mathbb N}^*$, $a_0=0$, $\delta=0$ or $-1$, and where $\alpha,\beta \in {\mathbb C}$ are related to the parameters of the meta Hahn algebra by
\begin{equation}\label{eq:Conditiion for irrep 2} 
\xi=-\beta(2\alpha+\eta-(\beta+1)(1+2\delta)). 
\end{equation}
and such that $2\alpha+\eta +n(1+2\delta)\neq 0$ for all $ n\in {\mathbb N}$.

The proof will follow closely what was done for the finite dimensional situation in \cite{TVZ2025MetaHahn}. It is straightforward to see that this formulas define an irreducible representation of $m\mathfrak{H}$. Let us prove that they all have the given expressions. Start from 
    \begin{align}
        Z\mid{n}\,\rangle&=c_n\mid{n}\,\rangle+a_n\mid{n-1}\,\rangle,\\
        X\mid{n}\,\rangle&=d_n\mid{n}\,\rangle+b_n\mid{n-1}\,\rangle.
    \end{align}
    Together with relation \eqref{eq:relationsMetaHahn1} one arrives at 
    \begin{equation}
        \frac{b_{n-1}}{a_{n-1}}-\frac{b_n}{a_n}=1,
    \end{equation}
    and then obtains
    \begin{equation}
        b_n=a_n (n+\beta). 
    \end{equation}
    Irreducibility imposes $a_n\neq 0$ for all $n\geq 0$. One also have $c_n(c_n+1)=0$ leading to $c_n=0$ or $-1$. Introduce
    \begin{equation}
         V\mid{n}\,\rangle=e_n\mid{n}\,\rangle+f_n\mid{n+1}\,\rangle.
    \end{equation}
    Using relation \eqref{eq:relationsMetaHahn3}, one finds that $f_n(c_n-c_{n+1})=0$ and since irreducibility implies $f_n\neq 0$ for all $n\geq 0$ we set $c_n=\delta$ with $\delta=0$ or $-1$. Then relation \eqref{eq:relationsMetaHahn1} leads to 
    \begin{equation}
        d_n=n(1+2\delta)+\alpha. 
    \end{equation}
    Next, using relation \eqref{eq:relationsMetaHahn3} we have 
    \begin{equation}
        f_n=f_{n-1}-2d_n-\eta,
    \end{equation}
    leading to 
    \begin{equation}
        f_n=-\frac{(n+1)(2\alpha+\eta+n(1+2\delta))}{a_{n+1}}.
    \end{equation}
    Finally, the formula for $e_n$ is obtained using relation \eqref{eq:relationsMetaHahn3} which leads to
    \begin{equation}
        e_n=-n(n-1+2\beta)+e_0. 
    \end{equation}
    Relation \eqref{eq:relationsMetaHahn2} will then enforce the condition \eqref{eq:Conditiion for irrep 2} and also fixes $e_0=-\beta(\beta+1)$.

\label{prop:negativeType}
Two-diagonal irreducible representations of the negative type of $m\mathfrak{H}$ acting on ${\mathbb C}^{\mathbb N}$ are described by the following operators
\begin{align}
    Z\mid{n}\,\rangle&=\delta\mid{n}\,\rangle+a_n\mid{n+1}\,\rangle\\
    X\mid{n}\,\rangle&=(-n(1+2\delta)-\alpha)\mid{n}\,\rangle+a_n(-n+\beta)\mid{n+1}\,\rangle\\
    V\mid{n}\,\rangle&=(n-\beta)(\beta-n+1)\mid{n}\,\rangle-\frac{n(2\alpha-\eta+(n-1)(1+2\delta))}{a_{n-1}}\mid{n-1}\,\rangle,
\end{align}
with $a_n\neq 0$ for all $n\in {\mathbb N}$, $\delta=0$ or $-1$, $\alpha,\beta \in {\mathbb C}$  are related to the parameters of the meta Hahn algebra by
\begin{equation}\label{eq:Conditiion for irrep 1} 
\xi=(\beta+1)(2\alpha-\eta+\beta(1+2\delta)). 
\end{equation}
and such that $2\alpha-\eta +(n-1)(1+2\delta)\neq 0 $ for all $ n\in {\mathbb N}$.

\label{prop:IndentificationContinuousHahn}
    The function $S_n(x)$ can be identified with continuous Hahn polynomials as follows
    \begin{equation}\label{eq:IdentificationContinuousHahn}
        S_n(x)=\frac{(-1-2\delta)^ni^n n!}{a_1\cdots a_n(n+a+b+c+d-1)_n(a+c)_n}p_n((1+2\delta )ix;a,b,c,d),
    \end{equation}
    with $a=-\delta\mu+(1+2\delta)\alpha$, $b=\beta+1-(1+\delta)\mu-(1+2\delta)(\alpha+\eta)$, $c=\beta+1+(1+\delta)\mu-(1+2\delta)\alpha$, and $d=(1+2\delta)(\alpha+\eta)+\delta \mu$.

This is a consequence of the explicit expressions \eqref{eq:Expression en*} and \eqref{eq:Expression wx} for $\langle\,{{v_n^+}^\dagger}|$ and $\mid{w_x^+}\,\rangle$. Indeed
\begin{align}
    \langle\,{{v_n^+}^\dagger}\mid{w_x^+}\,\rangle&=\frac{(2\alpha+\eta+\delta(n-1))_n}{a_1\cdots a_n(n+2\beta+1)_n}\\&\times\sum_{k=0}^n\sum_{\ell\geq 0} 
    \ \binom{n}{k}\frac{a_1\cdots a_k(n+2\beta+1)_k(x-\delta\mu-\alpha-(1+\delta)(\ell-1))_\ell}{a_1\cdots a_\ell(2\alpha+\eta+\delta(k-1))_k(\mu+\beta+1)_\ell}\langle k^\dagger\mid{\ell}\,\rangle.
\end{align}
Using $\langle k^\dagger\mid{\ell}\,\rangle=\delta_{k,\ell}$, one gets the result by looking separately at the two values $0$ and $-1$ for the representation parameter $\delta$ and the definition of $a,\ b,\ c$ and $d$ given in the Proposition.

\label{prop:IdentificationDualHahn}
For $n\in {\mathbb N}$ we have:
    \begin{equation}
    R_n(x)=\frac{(1+2\delta)^na_0\cdots a_{n-1}}{n!(a+b)_n}q_n(y^2;a,b,c)),
    \end{equation}
    with $iy=x+a$, $a=-\frac{2\beta+1}{2}$, $a+b=(1+2\delta)(2\alpha-\eta)$ and $a+c=-\mu-\beta$.

\label{prop:IdentificationPositive}
    The transition coefficients $U_n(x)$ are explicitly related to the rational function $\mathcal{U}_n^\varepsilon(x)$ by the following expression
        \begin{equation}
        U_n(x)=\frac{((1+2\varepsilon)c+\varepsilon(n-1))_n}{a_1\cdots a_n(2b+n+1)_n}\mathcal{U}_n^\varepsilon(x;a,b,c),
    \end{equation}
    where $a=\alpha$, $b=\beta$, $c=(1+2\delta)(2\alpha+\eta)$, and $\varepsilon=\delta$.

The recurrence relation is obtained from the corresponding relation on the transition coefficients $U_n(x)=\langle\,{v_n^+}^\dagger\mid{d_x^+}\,\rangle$ which is a consequence of the GEVP \eqref{eq:Def GEVP} 
    \begin{equation}
        \lambda_x \langle\,{v_n^+}^\dagger|~X\mid{d_x^+}\,\rangle =\langle\,{v_n^+}^\dagger|~Z\mid{d_x^+}\,\rangle.
    \end{equation}
    The proof is then a consequence of the explicit actions of $X$ and $Z$ on the vectors $\langle\,{v_n^+}^\dagger|$ combined with the identification proved in Proposition \ref{prop:IdentificationPositive}.

The rational functions $\mathcal{U}_n^\varepsilon(x;a,b,c)$
satisfy the following difference equation
\begin{multline}\label{eq:DifferenceEquationUn}
    (n+b)(n+b+1)\left( \mathcal{U}_n^\varepsilon(x;a,b,c)+\frac{a-x-(1+\varepsilon)(b+1)}{b+x+1}\mathcal{U}_n^\varepsilon(x+1;a,b,c)\right)\\
    =U_{x-1}\mathcal{U}_n^\varepsilon(x-1;a,b,c)+U_x\mathcal{U}_n^\varepsilon(x;a,b,c)+U_{x+1}\mathcal{U}_n^\varepsilon(x+1;a,b,c),
\end{multline}
where
\begin{align*}
    U_{x-1}&=\frac{x(x+1)(a-x-(1+\varepsilon)(b+1)}{b+x+1},\\ 
    U_x&=(1+2\varepsilon)b(c-b-1)+2x^2+x((1+2\varepsilon)c-2a),\\
    U_{x+1}&= -((1+2\varepsilon)c-a+x-(1+\varepsilon)(b+1))(b+x) .
\end{align*}

Recalling that $\langle {v_n^+}^\dagger|$ is an eigenvector of $V^\top$ with eigenvalue $\rho_n=-(n+\beta)(n+\beta+1)$, we have the following 
    \begin{equation}
        \rho_n\langle\,{v_n^+}^\dagger|Z\mid{\ d^+_x}\,\rangle=\left(\langle\,{v_n^+}^\dagger|V^\top \right)|Z\mid{\ d^+_x}\,\rangle=\langle\,{v_n^+}^\dagger|VZ \mid{\ d^+_x}\,\rangle. 
    \end{equation}
    Using the action of $VZ$ and $Z$ on $\mid{d_x^+}\,\rangle$ described in \eqref{eq:VZactionOn dx PositiveCase} and \eqref{eq:ZactionOn dx PositiveCase} this is equivalent to 
    \begin{multline}
        \rho_n\left( Z_{x,x}^{(d^+)})\langle\,{v_n^+}^\dagger\mid{\ d^+_x}\,\rangle+Z_{x+1,x}^{(d^+)})\langle\,{v_n^+}^\dagger\mid{\ d^+_{x+1}}\,\rangle\right)=\\
        VZ_{x-1,x}^{(d^+)}\langle\,{v_n^+}^\dagger\mid{\ d^+_{x-1}}\,\rangle+VZ_{x,x}^{(d^+)}\langle\,{v_n^+}^\dagger\mid{\ d^+_{x}}\,\rangle+VZ_{x+1,x}^{(d^+)}\langle\,{v_n^+}^\dagger\mid{\ d^+_{x+1}}\,\rangle.
    \end{multline}
    Looking at the explicit expressions for the coefficients and using the identification of parameters $a=\alpha$, $b=\beta$, $c=(1+\varepsilon)(2\alpha+\eta)$ and $\varepsilon=\delta$ lead to the result.

Assume the real part of 
    \begin{equation}
        (1+2\varepsilon)a,\ b-(1+2\varepsilon)a)+1,\ c,\  2b-c+1,\ \text{and } b-c+(1+2\varepsilon)a+1,
    \end{equation}
    are all positive. 
    The rational functions $\mathcal{U}^\varepsilon_n(x;a,b,c)$ and $\mathcal{V}^\varepsilon_n(x;a,b,c)$ satisfy the following biorthogonality relation 
    \begin{equation}
        \int_{-\infty}^{+\infty} \mathcal{U}_n^\varepsilon(ix;a,b,c)\mathcal{V}_k^\varepsilon(ix;a,b,c)w(x)~dx=\frac{2\pi n!\Gamma(c)\Gamma(n+2b-c+2)}{(c)_n(2n+2b+1)\Gamma(n+2b+1)}\delta_{n,k},
    \end{equation}
    where the weight $w(x)$ is given by
    \begin{multline}\label{eq:WeightUnVn}
            w(x)=B(-\varepsilon ix +(1+2\varepsilon)a,(1+\varepsilon)ix+b-(1+2\varepsilon)a+1)\\\times B(\varepsilon ix+c-(1+2\varepsilon)a+\varepsilon+1,-(1+\varepsilon)ix+b-c+(1+2\varepsilon)a-\varepsilon+1).
    \end{multline}

Using the integral representations \eqref{eq:IntegralUn} and \eqref{eq:IntegralVn} together with \eqref{eq:WeightUnVn} we prove
    \begin{multline}
        \int_{-\infty}^{+\infty} \mathcal{U}_n^\varepsilon(ix;a,b,c)\mathcal{V}_k^\varepsilon(ix;a,b,c)w(x)~dx= \frac{n!k!}{(c)_n(c)_k}\\
       \times\int_0^1\int_0^1\left( \int_{-\infty}^{+\infty}\left(\frac{u}{v}\right)^{\varepsilon ix}\left( \frac{1-u}{1-v}\right)^{(1+\varepsilon) ix}~dx\right)u^{(1+2\varepsilon)a-1}(1-u)^{b-(1+2\varepsilon)a}P_n^{(c-1,b-c-1)}(1-2u)\\
        \times v^{c-(1+2\varepsilon)a+\varepsilon}(1-v)^{b-c+(1+2\varepsilon)a-\varepsilon}P_k^{(c-1,b-c-1)}(1-2v)~dudv
    \end{multline}
    The following formula holds true
    \begin{equation}
        \int_{-\infty}^{+\infty}\left( \frac{u}{v}\right)^{\varepsilon ix}\left( \frac{1-u}{1-v}\right)^{(1+\varepsilon) ix}~dx=2\pi u^{-\varepsilon}(1-u)^{1+\varepsilon}\delta (u-y).
    \end{equation}
    Indeed, for $\varepsilon =0$ we have
\begin{equation}
\int_{-\infty}^{+\infty}\left( \frac{1-u}{1-v}\right)^{-ix}~dx=\int_{-\infty}^{+\infty}e^{-ix \ln \left(\frac{1-u}{1-v}\right)}~dx=2\pi \delta \left(\ln\left(\frac{1-u}{1-v}\right)\right)=2\pi (1-u) \delta(u-v).
\end{equation}
The case $\varepsilon=-1$ is proved similarly. 
    This leads to 
    \begin{multline}
        \int_{-\infty}^{+\infty} \mathcal{U}_n^\varepsilon(ix;a,b,c)\mathcal{V}_k^\varepsilon(ix;a,b,c)w(x)~dx= \frac{2\pi n!k!}{(c)_n(c)_k}\\
        \times \int_0^1 u^{c-1}(1-u)^{2b-c+1}P_n^{(c-1,2b-c+1)}(1-2u)P_k^{(c-1,2b-c+1)}(1-2u)~du.
        \end{multline}
        We end the proof using the orthogonality relation \eqref{eq:OrthogonalityJacobi} for the Jacobi polynomials .

\label{prop:IdentificationNegative}
The transition coefficients $F_n(x)$ are expressed in terms of the functions $\mathcal{F}_n$ as follows
\begin{equation}
    F_n(x)=\frac{a_0\cdots a_{n-1}(-1)^{n+1}(b-n)_n}{n!}\mathcal{F}_n(x;a,b,c).
\end{equation}
with $a=2\beta+1$, $b=\alpha-\beta$, and $c=-2\alpha+\eta$.

The rational functions $\mathcal{F}_n(x;a,b,c)$ satisfy the following three term recurrence relation 
\begin{multline}\label{eq:RecurrenceRelation Rational Functions F_n}
A_n\mathcal{F}_{n+1}(x;a,b,c)+B_n\mathcal{F}_n(x;a,b,c)_n+C_n\mathcal{F}_{n-1}(x;a,b,c) \\
=(x-\beta)(\beta-x+1)\left[-\mathcal{F}_n(x;a,b,c)+\frac{n}{n+\beta+\alpha}\mathcal{F}_{n-1}(x;a,b,c) \right],
\end{multline}
where 
\begin{align}
    A_n&=(2\alpha-\eta-n)(\beta-\alpha+n+1),\\
    B_n&= 2n^2+\eta n- 4\alpha n+2\alpha^2 - 2\alpha\beta + \beta^2 - \alpha\eta + \beta\eta  - 2\alpha + \beta+ \eta,\\
    C_n&=\frac{n(\alpha-n)(\alpha-n+1)}{\alpha-\beta-n}.
\end{align}

Since $\mid{v_x^-}\,\rangle$ is an eigenvector for $V$ with eigenvalue $\rho_x$ the  following relation holds true
    \begin{equation}
        \rho(x)\langle\,{d_n^-}^*|~Z\mid{v_x^-}\,\rangle=\langle\,{d_n^-}^*|~ZV\mid{v_x^-}\,\rangle.
    \end{equation}
    Using the actions \eqref{eq:ZactionOn dn} and \eqref{eq:ZVactionOn dn}, one can obtain the actions of $Z^\dagger$ and $(ZV)^\dagger$ on $\langle\,{d_n^-}^*|$ via the duality relation \eqref{eq:dualityd_n}. These actions together with the identification made in Proposition \ref{prop:IdentificationNegative} lead to the desired result.

The rational functions $\mathcal{F}_n(x;a,b,c)$ satisfy the following difference equation
    \begin{multline}
        X_{x,x+1}\mathcal{F}_n(x+1)+X_{x,x}\mathcal{F}_n(x)+X_{x,x-1}\mathcal{F}_n(x-1)=\\
        (\alpha-n)\left[Z_{x,x+1}\mathcal{F}_n(x+1)+Z_{x,x}\mathcal{F}_n(x)+Z_{x,x-1}\mathcal{F}_n(x-1)\right],
    \end{multline}
    where $X^{(v^-)}_{x+1,x},X^{(v^-)}_{x,x},X^{(v^-)}_{x-1,x}$ and $Z^{(v-)}_{x+1,x},Z^{(v-)}_{x,x},Z^{(v-)}_{x-1,x}$ where defined in \eqref{eq:Zaction on vx} and \eqref{eq:Xaction on vx}.

The result is obtained in a similar fashion as for the recurrence equation \eqref{eq:Recurrence for U} using the fact that $\langle\,{d_n^-}^*|$ satisfy the generalized eigenvalue problem
    \begin{equation}
    \langle\,{d_n^-}^*|X^\top=\rho_n \langle\,{d_n^-}^*|Z^\top. 
    \end{equation}
    Applying this equality to the vectors $\mid{ v_x^-}\,\rangle$ and using the actions of $Z$ and $X$ on the vectors $\mid{v_x^-}\,\rangle$ given in the equations \eqref{eq:Zaction on vx} and \eqref{eq:Xaction on vx}.

\label{thm:biorthogonality-F}
    Let $\alpha,\beta,\eta$ satisfy \eqref{eq:positivity-conditions} and let $n,m\in{\mathbb N}$. Then
    \begin{equation}\label{eq:biorthogonality-F}
        \frac{1}{2\pi}\int_{0}^{\infty} \mathcal{F}_n(x)\,\Theta_m(y)\,W_m(y)\,dy
        \;+\;\sum_{j=0}^{J_m-1}\lambda^{(m)}_j\,\mathcal{F}_n(x_{m,j})\,\Theta_m(y_{m,j})=h_n\,\delta_{n,m},
    \end{equation}
    with $x=\beta+\frac12+iy$ in the integral,
    \begin{equation}\label{eq:hn-F}
        h_n=\frac{n!\,\Gamma(\eta-2\alpha)\Gamma(\eta-\alpha+\beta)\Gamma(\alpha-\beta-1-n)}{(\alpha-\beta-n)_n},
    \end{equation}
    and where the discrete part is carried by the $J_m=\max(0,\lceil -c_m\rceil)$ points
    \begin{equation}\label{eq:mass-points}
    y_{m,j}=i(c_m+j),\qquad x_{m,j}=\beta+1-\alpha+m-j, \qquad 0\le j<J_m,
    \end{equation}
    that is, by those $j\ge0$ with $c_m+j<0$, with masses
    \begin{equation}\label{eq:masses}
    \lambda^{(m)}_j=\frac{\Gamma(a-c_m)\Gamma(b-c_m)\Gamma(a+c_m)\Gamma(b+c_m)}{\Gamma(-2c_m)}\;
    \frac{(-1)^j\,(2c_m)_j\,(c_m+1)_j\,(a+c_m)_j\,(b+c_m)_j}{j!\,(c_m)_j\,(c_m-a+1)_j\,(c_m-b+1)_j},
    \end{equation}
    where $a= -\beta-\tfrac12$ and $b=\eta-2\alpha+\beta+\tfrac12$.

\label{lem:overlaps}
For $k,m\in{\mathbb N}$,
\begin{equation}\label{eq:overlaps}
    \Omega_{k,m}:=\langle\,{ {w_k^-}^\dagger}|~Z\mid{d^-_m}\,\rangle=-a_m\cdots a_{k-1}\frac{(-1)^k(-k)_m\,(m+1-\mu-\alpha)_{k-m}}{k!}.
\end{equation}

A direct computation using \eqref{eq:ExpressionDn-} and \eqref{eq:normalized-R} together with the Chu--Vandermonde summation gives
\begin{equation}
\langle\,{{w_k^-}^\dagger}\mid{d^-_m}\,\rangle=a_m \cdots a_{k-1}\frac{(-1)^k(-k)_m\,(m-\mu-\alpha)_{k-m}}{k!},
\end{equation}
and the result follows directly using $Z\mid{d^-_m}\,\rangle=-\mid{d^-_m}\,\rangle+\mid{d^-_{m+1}}\,\rangle$.

\label{lem:G-closed-form}
Assume $\mathrm{Re}(\mu+\alpha)<1$, $\eta-\alpha+\beta>0$ and $0\le m<\alpha-\frac12$. Then the series
\begin{equation}\label{eq:def-Gm-series}
G_m(y):=\sum_{k\geq 0}\frac{k!(-1)^k}{a_m\cdots a_{k-1}(a+c)_k}\frac{\tilde{q}_k(y^2)}{\tilde{h}_k}\,\Omega_{k,m},\qquad x=\beta+\tfrac12+iy,
\end{equation}
converges and admits the closed form
\begin{multline}\label{eq:G-closed-form}
G_m(y)=\frac{(-1)^{m+1}}{\Gamma(\eta-2\alpha)\Gamma(\eta-\alpha+\beta)\Gamma(\alpha-\beta-1-m)}
\left|\frac{\Gamma(\alpha-\frac12-m+iy)}{\Gamma(c+iy)}\right|^{2} \\
\times (b-iy)_m\;\,\mbox{}_{3}F_{ 2}\!\left(\begin{array}{c} -m,\;a+iy,\;\alpha-\frac12-m+iy\\\alpha-\beta-1-m,\;1-b-m+iy\end{array} ; 1\right).
\end{multline}

Insert \eqref{eq:overlaps} and \eqref{eq:hhat} in \eqref{eq:def-Gm-series} and use $(-\mu-\beta)_k=(a+c)_k$ to get
\begin{equation}\label{eq:Gm-step1}
G_m(y)=\frac{-1}{\Gamma(a+b)\Gamma(a+c)\Gamma(b+c)}\sum_{k\geq 0}\frac{(-k)_m(m+1-\mu-\alpha)_{k-m}\,(a+b)_k}{k!\,(b+c)_k}\,\hat R_k(x).
\end{equation}
Next, since $b+c=1+\beta-\mu+\eta-2\alpha=(1-\mu-\alpha)+(\eta-\alpha+\beta)$, the Euler Beta integral gives
\begin{equation}
\frac{(m+1-\mu-\alpha)_{k-m}}{(b+c)_k}=\frac{\Gamma(b+c)}{\Gamma(m+1-\mu-\alpha)\,\Gamma(\eta-\alpha+\beta)}\int_0^1 s^{k-\mu-\alpha}\,(1-s)^{\eta-\alpha+\beta-1}\,ds ,
\end{equation}
which converts the $k$-dependent quotient into the $k$-th power $s^{k}$ under the integral sign. Using furthermore $(-k)_m s^k=(-1)^m s^{m}\frac{d^m}{ds^m}s^{k}$ and the generating function of the continuous dual Hahn polynomials \cite{koekoek2010hypergeometric}
\begin{equation}\label{eq:GF-CDH}
\sum_{k\geq0}\frac{q_k(y^2)}{(a+c)_k\,k!}\,s^k=(1-s)^{-b+iy}\,\mbox{}_{2}F_{ 1}\!\left(\begin{array}{c} a+iy,\;c+iy\\a+c\end{array} ; s\right),
\qquad q_k=(a+b)_k(a+c)_k\,\tilde{q}_k ,
\end{equation}
one obtains
\begin{multline}\label{eq:Gm-step2}
G_m(y)=\frac{(-1)^{m+1}}{\Gamma(a+b)\Gamma(a+c)\Gamma(m+1-\mu-\alpha)\Gamma(\eta-\alpha+\beta)}\\ \times\int_0^1 s^{m-\mu-\alpha}(1-s)^{\eta-\alpha+\beta-1}\,\frac{d^m}{ds^m}\Big[(1-s)^{-b+iy}\,\mbox{}_{2}F_{ 1}\!\left(\begin{array}{c} a+iy,\;c+iy\\a+c\end{array} ; s\right)\Big]ds .
\end{multline}
The $m$-th derivative is expanded with the Leibniz rule, using $\frac{d^r}{ds^r}\,{}_2F_1(A,B;C;s)=\frac{(A)_r(B)_r}{(C)_r}{}_2F_1(A+r,B+r;C+r;s)$. Each resulting term is an Euler-type integral which is evaluated via \eqref{eq:IntegralRep3F2} type integrals. More precisely,
\begin{equation}
\int_0^1 s^{e-1}(1-s)^{f-1}\,\mbox{}_{2}F_{ 1}\!\left(\begin{array}{c} A,B\\C\end{array} ; s\right)\,ds=B(e,f)\;\,\mbox{}_{3}F_{ 2}\!\left(\begin{array}{c} A,B,e\\C,e+f\end{array} ; 1\right),
\end{equation}
with $e=m+1-\mu-\alpha$ and $f=\alpha-\frac12-m+r+iy$ in the term labeled by $r$ ($0\le r\le m$). The key observation is that in each term the parameter $e+f=c+r+iy$ coincides with the numerator parameter $c+iy+r$ of the shifted ${}_2F_1$, so that the ${}_3F_2$ collapses to a ${}_2F_1$ evaluated at $1$, summed by the Gauss formula:
\begin{equation}
\,\mbox{}_{2}F_{ 1}\!\left(\begin{array}{c} a+iy+r,\;e\\a+c+r\end{array} ; 1\right)=\frac{\Gamma(a+c+r)\,\Gamma(\alpha-\frac12-m-iy)}{\Gamma(c-iy)\,\Gamma(\alpha-\beta-1-m+r)} .
\end{equation}
Collecting all factors and recognizing the sum over $r$ as a terminating ${}_3F_2$ of unit argument yields \eqref{eq:G-closed-form}. The stated conditions ensure the convergence of all the integrals involved.

We first treat the case $m<\alpha-\frac12$, for which $J_m=0$ and the statement reduces to \eqref{eq:biorthogonality-F-simple}.
Fix $0\leq  m<\alpha-\frac12$ and choose first $\mu$ such that $\mathrm{Re}(\mu+\alpha)<1$ this is possible since $\mu$ is a free parameter of the basis $\{\mid{w_k^-}\,\rangle\}$ and the assertion of the theorem does not involve it. Since the form $\langle\,{{d^-_n}^*|}$ is supported on $\langle\,{0^\dagger}|,\dots,\langle\,{n^\dagger}|$ and the forms $\langle\,{{w_k^-}^\dagger|}$, $0\le k\le n$, constitute a triangular basis of the space of such forms, there are unique coefficients $g_{n,k}=\langle\,{d_n^-}^\star\mid{w_k^-}\,\rangle$ such that
\begin{equation}
\langle\,{{d^-_n}^*}|=\sum_{k=0}^n g_{n,k}\langle\,{{w_k^-}^\dagger|},
\qquad\text{leading to}\qquad
\mathcal{F}_n(x)=\sum_{k=0}^n g_{n,k}\,\hat R_k(x).
\end{equation}
Using \eqref{eq:resolutionIdentity}, \eqref{eq:hhat} and Lemma \ref{lem:G-closed-form}, the interchange of summation and integration being justified by the convergence conditions,
\begin{equation}
\int_0^{\infty}\mathcal{F}_n\,G_m\,d\sigma_\mu
=\sum_{k=0}^{n} g_{n,k}\,\Omega_{k,m}
=\langle\,{{d^-_n}^*}|Z\mid{d^-_m}\,\rangle=\kappa_n\,\delta_{n,m},
\end{equation}
the last equality being obtained using Equation \eqref{eq:InnerProductGEVP}. It remains to substitute the closed form \eqref{eq:G-closed-form} of $G_m$. Since
\begin{equation}
\left|\Gamma(\alpha-\tfrac12-m+iy)\right|^{2}=\frac{\left|\Gamma(\alpha-\tfrac12+iy)\right|^{2}}{(x+\alpha-\beta-1-m)_m\,(\alpha+\beta-m-x)_m}
\end{equation}
on the line $x=\beta+\frac12+iy$, one has
\begin{equation}
G_m(y)\,d\sigma_\mu(y)=\frac{(-1)^{m+1}}{\Gamma(\eta-2\alpha)\Gamma(\eta-\alpha+\beta)\Gamma(\alpha-\beta-1-m)}\;\mathcal{G}_m(x)\,\frac{W(y)}{2\pi}\,dy,
\end{equation}
the factors $|\Gamma(c+iy)|^{2}$ canceling between \eqref{eq:G-closed-form} and \eqref{eq:sigma-mu}. The parameter $\mu$ has completely disappeared, and the resulting identity is precisely \eqref{eq:biorthogonality-F-simple} with $h_n$ as in \eqref{eq:hn-F}, upon using $(1+\beta-\alpha)_n=(-1)^n(\alpha-\beta-n)_n$; by \eqref{eq:factorization-GW} this is \eqref{eq:biorthogonality-F} in the case at hand.

For arbitrary $m$ the argument is unchanged up to the last step. Both sides of \eqref{eq:biorthogonality-F} are, for fixed $n$ and $m$, analytic in the parameters; the left-hand side of \eqref{eq:biorthogonality-F-simple}, written as in \eqref{eq:factorization-GW}, is the continuous dual Hahn functional with parameters $(a,b,c)$ evaluated at $c=c_m$ on the function $\mathcal{F}_n\Theta_m$ which is independent of $c$. That functional is analytic in $c$ on $\mathrm{Re}\,c>0$, and its analytic continuation past $c=0$ is obtained by deforming the contour so as to keep the poles of $\Gamma(c\pm iy)$ on their original sides. The poles that must be recaptured are those at $y=\mp i(c+j)$ with $c+j<0$; writing the integral as $\frac{1}{4\pi i}\int_{-i\infty}^{i\infty}(\cdots)\,dz$ with $z=iy$, each pair contributes the residue of
\begin{equation}
\frac{\Gamma(a+z)\Gamma(b+z)\Gamma(c+z)\Gamma(a-z)\Gamma(b-z)\Gamma(c-z)}{\Gamma(2z)\Gamma(-2z)}
\end{equation}
at $z=-c-j$, which is
\begin{equation}
\frac{(-1)^j}{j!}\,\frac{\Gamma(a-c-j)\Gamma(b-c-j)\Gamma(a+c+j)\Gamma(b+c+j)\Gamma(2c+j)}{\Gamma(-2c-2j)\Gamma(2c+2j)} .
\end{equation}
Rewriting the shifted Gamma functions in terms of Pochhammer symbols through $\Gamma(a-c-j)=\Gamma(a-c)/(a-c-j)_j$, $(a-c-j)_j=(-1)^j(1+c-a)_j$, $\Gamma(-2c-2j)=\Gamma(-2c)/(1+2c)_{2j}$ and $(1+2c)_{2j}/(2c+j)_j=(2c)_j(c+1)_j/(c)_j$ turns this residue into \eqref{eq:masses}, evaluated at $c=c_m$. Since $\mathcal{F}_n\Theta_m$ is regular at these points, the continuation of the functional is the left-hand side of \eqref{eq:biorthogonality-F}, while its value $h_n\delta_{n,m}$ is unchanged, being analytic in the parameters throughout.

It is natural to ask how \eqref{eq:biorthogonality-F} sits with respect to the general biorthogonality of Gupta and Masson \cite{gupta1998contiguous}, which stands at the top of a scheme of rational biorthogonalities and from which many others are obtained by degeneration. The two are of different types in the following sense. Their functions are of the $R_{II}$ type of Ismail and Masson \cite{ismail1995generalized}, with two interpolation points at each step and \emph{both} biorthogonal families rational. On the other hand, the recurrence \eqref{eq:RecurrenceRelation Rational Functions F_n} is of the $R_I$ type : one interpolation point, one polynomial family and one rational family. More precisely, solving the recurrence relation \eqref{eq:RecurrenceRelation Rational Functions F_n} for $\mathcal{F}_{n+1}$ puts it in the form $\mathcal{F}_{n+1}=(z-c_n)\mathcal{F}_n-\lambda_n(z-a_n)\mathcal{F}_{n-1}$ (up to normalization) in the variable $z=\mu(x)$, with nodes $a_n=-( \alpha-n)(\alpha-n+1)$. Accordingly, the rational functions naturally associated with the second series are
\begin{equation}
\frac{\mathcal{F}_n(x)}{\prod_{j=1}^{n}(\mu(x)+(\alpha-j)(\alpha-j+1))}
=\frac{\mathcal{F}_n(x)}{(x+\alpha-\beta-n)_n\,(\alpha+\beta+1-n-x)_n},
\end{equation}
in accordance with the general theory of \cite{zhedanov1999biorthogonal}. Observe that the partner functions $\mathcal{G}_m$ of \eqref{eq:def-G} have their poles at the reflected nodes.
The $R_I$ case is the degeneration of $R_{II}$ in which one interpolation point is sent to infinity, so the present system does sit below theirs in the hierarchy, but that degeneration is not effected by a specialization of the parameters that leaves the lattice untouched. The natural setting for \eqref{eq:biorthogonality-F} is therefore the $R_I$ theory of Ismail and Masson \cite{ismail1995generalized}, of which it provides an explicit continuous instance.
